const fs = require('fs');
const path = require('path');

// ============================================================
// generar_456_reconocer_vet.js
// ============================================================
// EL PROBLEMA (de la captura)
// Escribir "vet", "veterinario" o "cuando fue al vet" respondia "eso
// esta fuera de lo que puedo consultar". Mis frases eran largas —"fue
// al veterinario", "cuando fue al vet"— pero la palabra sola no
// enganchaba, y "cuando fue al vet" tampoco por una diferencia minima.
//
// AHORA
//   "vet" o "veterinario" a secas ofrece los dos caminos posibles:
//     ¿Quieres saber cuándo fue la última visita, o preparar la
//     próxima consulta?
//     [¿Cuándo fue al veterinario?] [¿Qué le cuento al veterinario?]
//
//   Y se amplian las formas de preguntarlo: "fue al vet", "ultima
//   visita", "cuando lo lleve", "cuando fuimos".
//
// Si algo no calza, ABORTA sin escribir.
// ============================================================

const RUTA = 'components/ChiquiChat.tsx';
const CHAT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico ningun archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const destino = path.join(process.cwd(), RUTA);
if (!fs.existsSync(destino)) {
  abortar('no se encontro ' + RUTA + '. Corre primero el script 454.');
}

const actual = fs.readFileSync(destino, 'utf8');
if (actual.includes("palabras: ['vet', 'veterinario', 'veterinaria']")) {
  abortar('el chat ya reconoce "vet". Parece que este script ya se corrio.');
}
if (!actual.includes("tema: 'viaje_auto'")) {
  abortar('falta el script 454. Correlo primero.');
}

const comp = Buffer.from(CHAT_B64, 'base64').toString('utf8');

const REQUERIDOS = [
  "'use client'",
  'export default function ChiquiChat',
  "palabras: ['vet', 'veterinario', 'veterinaria']",
  '¿Quieres saber cuándo fue la última visita',
  "'fue al vet'",
  "tema: 'viaje_auto'",
  "case 'visitas'",
  'const EMERGENCIAS',
];
for (const r of REQUERIDOS) {
  if (!comp.includes(r)) {
    abortar('el contenido nuevo no incluye [' + r + ']. Script corrupto, no se escribio nada.');
  }
}
console.log('  OK  el contenido nuevo reconoce "vet"');

fs.writeFileSync(destino, comp, 'utf8');
console.log('');
console.log('OK: ' + RUTA);
console.log('');
console.log('IMPORTANTE: corre despues el script 455, que le pasa las visitas.');
console.log('Sin el, el chat sabe responder pero no tiene los datos.');
console.log('');
console.log('Listo. "vet" y "veterinario" ya se reconocen.');
